#[derive(Debug, Error)]
pub enum AutomationRunError {
    #[error("job error: {0}")]
    Job(#[from] JobStoreError),
    #[error("io error: {0}")]
    Io(#[from] std::io::Error),
    #[error("image error: {0}")]
    Image(#[from] image::ImageError),
    #[error("json error: {0}")]
    Json(#[from] serde_json::Error),
    #[error("asset processing failed: {0}")]
    Processing(String),
    #[error("{0}")]
    Provider(#[from] ProviderError),
    #[error("plan store error: {0}")]
    Plan(#[from] PlanStoreError),
    #[error("{0}")]
    GameArt(#[from] crate::game_art::GameArtError),
    #[error("job was cancelled")]
    Cancelled,
    #[error("project build failed: {0}")]
    ProjectBuildFailed(String),
}

impl AutomationRunError {
    pub fn code(&self) -> &'static str {
        match self {
            Self::Job(_) => "job_error",
            Self::Io(_) => "io_error",
            Self::Image(_) => "image_error",
            Self::Json(_) => "invalid_json",
            Self::Processing(_) => "automation_failed",
            Self::Provider(error) => error.code(),
            Self::Plan(_) => "plan_store_error",
            Self::GameArt(error) => error.code(),
            Self::Cancelled => "cancelled",
            Self::ProjectBuildFailed(_) => "project_build_failed",
        }
    }
}

pub fn stage_plan_job(
    store: &JobStore,
    plan: &AutomationPlan,
) -> Result<JobRecord, AutomationRunError> {
    if let Some(repair) = &plan.repair {
        if let Some(child) = active_repair_child(store, &repair.source_job_id)? {
            return Err(AutomationRunError::Processing(format!(
                "source job already has an active repair job: {}",
                child.job_id
            )));
        }
    }
    let (source_kind, operation_kind) = match &plan.operation {
        AutomationOperation::PrepareAsset(request) => (
            source_kind_for_input(&request.input),
            JobOperationKind::PrepareAsset,
        ),
        AutomationOperation::PrepareCharacterPack(_) => {
            (SourceKind::FromCode, JobOperationKind::PrepareCharacterPack)
        }
        AutomationOperation::GenerateCharacterPack(_) => (
            SourceKind::FromCode,
            JobOperationKind::GenerateCharacterPack,
        ),
        AutomationOperation::ImportDirectionGrid(_) => (
            SourceKind::ImportSpriteSheet,
            JobOperationKind::ImportDirectionGrid,
        ),
        AutomationOperation::CreateStyleLock(_) => {
            (SourceKind::FromCode, JobOperationKind::CreateStyleLock)
        }
        AutomationOperation::CreateSubjectLock(_) => {
            (SourceKind::FromCode, JobOperationKind::CreateSubjectLock)
        }
        AutomationOperation::CreateCollectionLock(_) => {
            (SourceKind::FromCode, JobOperationKind::CreateCollectionLock)
        }
        AutomationOperation::GenerateStaticAssetSet(_) => (
            SourceKind::FromCode,
            JobOperationKind::GenerateStaticAssetSet,
        ),
        AutomationOperation::CreateEnvironmentLock(_) => (
            SourceKind::FromCode,
            JobOperationKind::CreateEnvironmentLock,
        ),
        AutomationOperation::GenerateTerrainSet(_) => {
            (SourceKind::FromCode, JobOperationKind::GenerateTerrainSet)
        }
        AutomationOperation::GenerateBuildingKit(_) => {
            (SourceKind::FromCode, JobOperationKind::GenerateBuildingKit)
        }
        AutomationOperation::CompileMap(_) => (SourceKind::FromCode, JobOperationKind::CompileMap),
        AutomationOperation::InstallGodot(_) => {
            (SourceKind::ImportGsfpack, JobOperationKind::InstallGodot)
        }
        AutomationOperation::BuildProject(_) => {
            (SourceKind::FromCode, JobOperationKind::BuildProject)
        }
    };
    let remediation_source = match &plan.operation {
        AutomationOperation::GenerateCharacterPack(request)
            if request.workflow.id == "topdown-grid" && request.workflow.version == "9.3.0" =>
        {
            request.reuse_from_job_dir.as_ref().map(|directory| {
                let selected_frames = request
                    .retry_frames
                    .get("walk_down")
                    .map(Vec::as_slice)
                    .unwrap_or_default();
                crate::grid_retry_source::validate_v92_laterality_source_closure(
                    directory,
                    selected_frames,
                )
                .map(|source| (source.job, "topdown-grid@9.3.0:walk_down:frame:2"))
                .map_err(|error| AutomationRunError::Processing(error.to_string()))
            })
        }
        AutomationOperation::GenerateCharacterPack(request)
            if request.workflow.id == "topdown-grid" && request.workflow.version == "9.4.0" =>
        {
            request.reuse_from_job_dir.as_ref().map(|directory| {
                let selected_frames = request
                    .retry_frames
                    .get("walk_down")
                    .map(Vec::as_slice)
                    .unwrap_or_default();
                crate::grid_retry_source::validate_v93_platform_source_closure(
                    directory,
                    selected_frames,
                )
                .map(|source| (source.job, "topdown-grid@9.4.0:walk_down:frame:2"))
                .map_err(|error| AutomationRunError::Processing(error.to_string()))
            })
        }
        AutomationOperation::GenerateCharacterPack(request)
            if request.workflow.id == "topdown-grid" && request.workflow.version == "9.5.0" =>
        {
            request.reuse_from_job_dir.as_ref().map(|directory| {
                let selected_frames = request
                    .retry_frames
                    .get("walk_down")
                    .map(Vec::as_slice)
                    .unwrap_or_default();
                crate::grid_retry_source::validate_v95_footwear_cleanup_source_closure(
                    directory,
                    selected_frames,
                )
                .map(|source| {
                    let scope = if source.job.lifecycle_state == JobLifecycleState::Failed {
                        "topdown-grid@9.5.0:walk_down:frame:2:zero-output-recovery"
                    } else {
                        "topdown-grid@9.5.0:walk_down:frame:2"
                    };
                    (source.job, scope)
                })
                .map_err(|error| AutomationRunError::Processing(error.to_string()))
            })
        }
        _ => None,
    }
    .transpose()?;
    let remediation_source_job = remediation_source.as_ref().map(|(job, _)| job);
    let mut record = if let Some((source, scope)) = &remediation_source {
        store
            .create_claimed_child_job(
                &source.job_dir,
                &source.job_id,
                scope,
                source_kind,
            )
            .map_err(|error| match error {
                JobStoreError::ChildScopeAlreadyClaimed { child_job_id, .. } => {
                    let code = if scope.starts_with("topdown-grid@9.3.0") {
                        "asymmetric_gait_source_already_consumed"
                    } else if scope.starts_with("topdown-grid@9.5.0") {
                        "footwear_cleanup_source_already_consumed"
                    } else {
                        "platform_safe_gait_source_already_consumed"
                    };
                    AutomationRunError::Processing(format!(
                        "{code}: source Job already reserved its sole remediation child as {child_job_id}"
                    ))
                }
                other => AutomationRunError::Job(other),
            })?
    } else {
        store.create_job(source_kind)?
    };
    let (asset_id, reuse_from_job_dir) = match &plan.operation {
        AutomationOperation::GenerateCharacterPack(request) => (
            request.asset_id.clone(),
            request.reuse_from_job_dir.as_ref(),
        ),
        AutomationOperation::GenerateStaticAssetSet(request) => (
            Some(request.asset.id.clone()),
            request.reuse_from_job_dir.as_ref(),
        ),
        AutomationOperation::ImportDirectionGrid(request) => {
            let source: JobRecord =
                serde_json::from_slice(&fs::read(request.source_job_dir.join("job.json"))?)?;
            (source.asset_id, Some(&request.source_job_dir))
        }
        AutomationOperation::GenerateTerrainSet(request) => (Some(request.asset.id.clone()), None),
        AutomationOperation::GenerateBuildingKit(request) => (Some(request.asset.id.clone()), None),
        _ => (None, None),
    };
    if asset_id.is_some() {
        record.asset_id = asset_id;
    }
    record.parent_job_id = remediation_source_job
        .as_ref()
        .map(|source| source.job_id.clone())
        .or_else(|| {
            plan.repair
                .as_ref()
                .map(|repair| repair.source_job_id.clone())
        })
        .or_else(|| {
            reuse_from_job_dir.and_then(|directory| {
                fs::read(directory.join("job.json"))
                    .ok()
                    .and_then(|bytes| serde_json::from_slice::<JobRecord>(&bytes).ok())
                    .map(|source| source.job_id)
            })
        });
    if let Some(source) = &remediation_source_job {
        record.lineage_root_job_id = source
            .lineage_root_job_id
            .clone()
            .or_else(|| Some(source.job_id.clone()));
        // Single-frame grid remediations always require a newly attached
        // authorization. Never inherit the source grant.
        record.authorization_id = None;
        record.authorization_manifest_sha256 = None;
    } else if let Some(parent_job_id) = record.parent_job_id.as_deref() {
        if let Ok(parent) = store.read_record(parent_job_id) {
            record.lineage_root_job_id = parent
                .lineage_root_job_id
                .clone()
                .or_else(|| Some(parent.job_id.clone()));
            let independent_scoped_probe =
                matches!(
                    &plan.operation,
                    AutomationOperation::GenerateCharacterPack(request)
                        if (is_topdown_cycle_v10(request)
                                && request.provider_id != "fixture"
                                && request.validation_only)
                            || super::plan::is_xai_image2_direction_grid_probe(request)
                ) || matches!(&plan.operation, AutomationOperation::ImportDirectionGrid(_));
            if independent_scoped_probe {
                // Paid probes and local external imports inherit approved
                // lineage, never the source Job's consumed authorization.
                record.authorization_id = None;
                record.authorization_manifest_sha256 = None;
            } else {
                record.authorization_id = parent.authorization_id.clone();
                record.authorization_manifest_sha256 = parent.authorization_manifest_sha256.clone();
            }
        } else {
            // The input closure already validates retry source artifacts. If a
            // legacy source Job is outside this Store, retain its stable id as
            // the lineage root without inventing authorization state.
            record.lineage_root_job_id = Some(parent_job_id.to_string());
        }
    } else {
        record.lineage_root_job_id = Some(record.job_id.clone());
    }
    record.operation_kind = operation_kind;
    record.lifecycle_state = JobLifecycleState::Queued;
    record.input_hash = Some(plan.input_fingerprint.clone());
    record.recipe_hash = Some(plan.recipe_hash.clone());
    record.recipe = Some(serde_json::to_value(&plan.operation)?);
    record.repair = plan.repair.clone();
    record.steps = steps_for_operation(&plan.operation);
    record.next_actions = vec!["poll_job".to_string(), "job_report".to_string()];
    write_json_atomic(&record.job_dir.join(JOB_WORKSPACE_JSON), plan)?;
    store.write_record(&record)?;
    Ok(record)
}

pub fn run_operation(
    store: &JobStore,
    job_id: &str,
    operation: &AutomationOperation,
) -> Result<JobRecord, AutomationRunError> {
    run_operation_with_provider(store, job_id, operation, None)
}

pub fn run_operation_with_provider(
    store: &JobStore,
    job_id: &str,
    operation: &AutomationOperation,
    provider: Option<&dyn MediaGenerationProvider>,
) -> Result<JobRecord, AutomationRunError> {
    let staged = store.read_record(job_id)?;
    let canonical_operation = serde_json::to_value(operation)?;
    let canonical_recipe_hash = format!("{:x}", Sha256::digest(serde_json::to_vec(operation)?));
    if staged.lifecycle_state != JobLifecycleState::Queued
        || staged.cancellation_requested
        || staged.recipe.as_ref() != Some(&canonical_operation)
        || staged.recipe_hash.as_deref() != Some(canonical_recipe_hash.as_str())
    {
        return Err(AutomationRunError::Processing(format!(
            "job_execution_not_queued: job {job_id} is {:?}, cancelled={}, or its immutable recipe does not match; a staged Job may execute exactly once",
            staged.lifecycle_state,
            staged.cancellation_requested
        )));
    }
    let current_input_fingerprint = match super::plan::fingerprint_operation_inputs(operation) {
        Ok(fingerprint) => fingerprint,
        Err(error) => {
            let error = match (operation, error) {
                (AutomationOperation::BuildProject(request), PlanStoreError::InvalidRequest(_)) => {
                    match crate::game_art::GameArtManifestV1::load_validated(&request.manifest_path)
                    {
                        Err(error) => AutomationRunError::GameArt(error),
                        Ok(_) => AutomationRunError::Processing(
                            "build project inputs changed after staging".into(),
                        ),
                    }
                }
                (_, PlanStoreError::Json(error)) => AutomationRunError::Json(error),
                (_, error) => AutomationRunError::Plan(error),
            };
            let message = error.to_string();
            let error_code = error.code();
            let _ = store.update_record(job_id, |record| {
                record.state = JobState::Failed;
                record.lifecycle_state = JobLifecycleState::Failed;
                record.worker_pid = None;
                record.error_summary = Some(message.clone());
                record.error_code = Some(error_code.into());
                record.recoverable = true;
                record.next_actions = vec!["job_report".into(), "prepare_new_plan".into()];
            });
            return Err(error);
        }
    };
    if staged.input_hash.as_deref() != Some(current_input_fingerprint.as_str()) {
        return Err(AutomationRunError::Processing(format!(
            "job_execution_not_queued: job {job_id} inputs changed after staging; a staged Job may execute exactly once"
        )));
    }
    if let Some(provider) = provider {
        let lineage_root = staged
            .lineage_root_job_id
            .as_deref()
            .unwrap_or(&staged.job_id);
        provider
            .set_authorization_execution_context(
                &staged.job_id,
                lineage_root,
                staged
                    .recipe_hash
                    .as_deref()
                    .expect("staged recipe hash was validated"),
                staged
                    .input_hash
                    .as_deref()
                    .expect("staged input hash was validated"),
            )
            .map_err(provider_error)?;
    }
    if let AutomationOperation::GenerateCharacterPack(request) = operation {
        if (is_topdown_grid_v93(request)
            || is_topdown_grid_v94(request)
            || is_topdown_grid_v95(request))
            && request.provider_id != "fixture"
        {
            let provider = provider.ok_or_else(|| {
                AutomationRunError::Processing(
                    "asymmetric_gait_authorization_required: V9.3 real execution requires an independently authorized Provider"
                        .into(),
                )
            })?;
            if provider.id() != request.provider_id {
                return Err(AutomationRunError::Processing(format!(
                    "resolved provider {} does not match plan provider {}",
                    provider.id(),
                    request.provider_id
                )));
            }
            let attached = staged.authorization_id.as_deref().ok_or_else(|| {
                AutomationRunError::Processing(
                    "asymmetric_gait_authorization_required: V9.3 Job has no independent authorization"
                        .into(),
                )
            })?;
            let provider_authorization = provider
                .durable_authorization_id()
                .map_err(provider_error)?
                .ok_or_else(|| {
                    AutomationRunError::Processing(
                        "asymmetric_gait_authorization_required: V9.3 Provider is not bound to a durable authorization"
                            .into(),
                    )
                })?;
            if provider_authorization != attached {
                return Err(AutomationRunError::Processing(
                    "asymmetric_gait_authorization_mismatch: Provider authorization does not match the staged Job"
                        .into(),
                ));
            }
            let attached_manifest_sha256 = staged
                .authorization_manifest_sha256
                .as_deref()
                .ok_or_else(|| {
                    AutomationRunError::Processing(
                        "asymmetric_gait_authorization_manifest_missing: V9.3 Job has no reviewed authorization manifest digest"
                            .into(),
                    )
                })?;
            let provider_manifest_sha256 = provider
                .durable_authorization_manifest_sha256()
                .map_err(provider_error)?
                .ok_or_else(|| {
                    AutomationRunError::Processing(
                        "asymmetric_gait_authorization_manifest_missing: V9.3 Provider has no bound authorization manifest digest"
                            .into(),
                    )
                })?;
            if provider_manifest_sha256 != attached_manifest_sha256 {
                return Err(AutomationRunError::Processing(
                    "asymmetric_gait_authorization_manifest_mismatch: Provider authorization manifest does not match the staged Job"
                        .into(),
                ));
            }
            let image_model = request.generation.image_model.as_deref().ok_or_else(|| {
                AutomationRunError::Processing(
                    "asymmetric_gait_authorization_model_missing: V9.3 recipe has no resolved image model"
                        .into(),
                )
            })?;
            provider
                .validate_durable_authorization_scope(
                    &request.provider_id,
                    &request.profile_id,
                    image_model,
                    "walk_down:frame:2",
                    1,
                    1,
                    1_400_000_000,
                    staged
                        .lineage_root_job_id
                        .as_deref()
                        .unwrap_or(&staged.job_id),
                    staged
                        .recipe_hash
                        .as_deref()
                        .expect("staged recipe hash was validated"),
                    staged
                        .input_hash
                        .as_deref()
                        .expect("staged input hash was validated"),
                )
                .map_err(provider_error)?;
            let source_dir = request.reuse_from_job_dir.as_deref().ok_or_else(|| {
                AutomationRunError::Processing(
                    "asymmetric_gait_source_missing: V9.3 requires its immutable V9.2 source"
                        .into(),
                )
            })?;
            let selected_frames = request
                .retry_frames
                .get("walk_down")
                .map(Vec::as_slice)
                .unwrap_or_default();
            let source_job = if is_topdown_grid_v95(request) {
                crate::grid_retry_source::validate_v95_footwear_cleanup_source_closure(
                    source_dir,
                    selected_frames,
                )
                .map(|source| source.job)
                .map_err(|error| AutomationRunError::Processing(error.to_string()))?
            } else if is_topdown_grid_v94(request) {
                crate::grid_retry_source::validate_v93_platform_source_closure(
                    source_dir,
                    selected_frames,
                )
                .map(|source| source.job)
                .map_err(|error| AutomationRunError::Processing(error.to_string()))?
            } else {
                crate::grid_retry_source::validate_v92_laterality_source_closure(
                    source_dir,
                    selected_frames,
                )
                .map(|source| source.job)
                .map_err(|error| AutomationRunError::Processing(error.to_string()))?
            };
            if staged.parent_job_id.as_deref() != Some(source_job.job_id.as_str())
                || staged.lineage_root_job_id.as_deref()
                    != Some(
                        source_job
                            .lineage_root_job_id
                            .as_deref()
                            .unwrap_or(&source_job.job_id),
                    )
            {
                return Err(AutomationRunError::Processing(
                    "asymmetric_gait_source_identity_changed: staged parent/lineage no longer matches the validated V9.2 source"
                        .into(),
                ));
            }
            if source_job.authorization_id.as_deref() == Some(attached) {
                return Err(AutomationRunError::Processing(
                    "asymmetric_gait_authorization_not_independent: V9.3 cannot reuse the V9.2 source authorization"
                        .into(),
                ));
            }
        }
        if super::plan::is_front_authoritative_direction_grid(request)
            && request.provider_id != "fixture"
        {
            let provider = provider.ok_or_else(|| {
                AutomationRunError::Processing(
                    "front_authoritative_direction_grid_authorization_required: independently authorized Provider is required"
                        .into(),
                )
            })?;
            let image_model = request.generation.image_model.as_deref().ok_or_else(|| {
                AutomationRunError::Processing(
                    "front_authoritative_direction_grid_model_missing".into(),
                )
            })?;
            if provider.id() != "xai" || request.profile_id != "default" {
                return Err(AutomationRunError::Processing(
                    "front_authoritative_direction_grid_scope_forbidden: staged Provider/profile is not xai/default"
                        .into(),
                ));
            }
            let attached = staged.authorization_id.as_deref().ok_or_else(|| {
                AutomationRunError::Processing(
                    "front_authoritative_direction_grid_authorization_required: staged Job has no independent authorization"
                        .into(),
                )
            })?;
            let provider_authorization = provider
                .durable_authorization_id()
                .map_err(provider_error)?
                .ok_or_else(|| {
                    AutomationRunError::Processing(
                        "front_authoritative_direction_grid_authorization_required: Provider has no durable authorization"
                            .into(),
                    )
                })?;
            let attached_manifest_sha256 = staged
                .authorization_manifest_sha256
                .as_deref()
                .ok_or_else(|| {
                    AutomationRunError::Processing(
                        "front_authoritative_direction_grid_authorization_manifest_missing: staged Job has no reviewed manifest digest"
                            .into(),
                    )
                })?;
            let provider_manifest_sha256 = provider
                .durable_authorization_manifest_sha256()
                .map_err(provider_error)?
                .ok_or_else(|| {
                    AutomationRunError::Processing(
                        "front_authoritative_direction_grid_authorization_manifest_missing: Provider has no bound manifest digest"
                            .into(),
                    )
                })?;
            if provider_authorization != attached
                || provider_manifest_sha256 != attached_manifest_sha256
            {
                return Err(AutomationRunError::Processing(
                    "front_authoritative_direction_grid_authorization_mismatch: Provider authorization or manifest does not match the staged Job"
                        .into(),
                ));
            }
            provider
                .validate_durable_authorization_scope(
                    "xai",
                    "default",
                    image_model,
                    "direction_grid",
                    1,
                    1,
                    super::FRONT_AUTHORITATIVE_DIRECTION_GRID_MAX_COST_TICKS,
                    staged
                        .lineage_root_job_id
                        .as_deref()
                        .unwrap_or(&staged.job_id),
                    staged
                        .recipe_hash
                        .as_deref()
                        .expect("staged recipe hash was validated"),
                    staged
                        .input_hash
                        .as_deref()
                        .expect("staged input hash was validated"),
                )
                .map_err(provider_error)?;
            let source_dir = request.reuse_from_job_dir.as_deref().ok_or_else(|| {
                AutomationRunError::Processing(
                    "front_authoritative_direction_grid_source_missing".into(),
                )
            })?;
            super::plan::validate_topdown_cycle_direction_source(request, source_dir)
                .map_err(AutomationRunError::Plan)?;
            let source_job: JobRecord =
                serde_json::from_slice(&fs::read(source_dir.join("job.json"))?)?;
            let source_lineage = source_job
                .lineage_root_job_id
                .as_deref()
                .unwrap_or(&source_job.job_id);
            if staged.parent_job_id.as_deref() != Some(source_job.job_id.as_str())
                || staged.lineage_root_job_id.as_deref() != Some(source_lineage)
                || source_job.authorization_id.as_deref() == Some(attached)
            {
                return Err(AutomationRunError::Processing(
                    "front_authoritative_direction_grid_source_identity_changed: parent, lineage, or independent authorization no longer matches the approved source"
                        .into(),
                ));
            }
        }
        if super::plan::is_xai_image2_direction_grid_probe(request) {
            let provider = provider.ok_or_else(|| {
                AutomationRunError::Processing(
                    "xai_image2_candidate_authorization_required: Image 2.0 DirectionGrid comparison requires an independently authorized Provider"
                        .into(),
                )
            })?;
            if provider.id() != "xai" || request.profile_id != "default" {
                return Err(AutomationRunError::Processing(
                    "xai_image2_candidate_scope_forbidden: staged Provider/profile is not xai/default"
                        .into(),
                ));
            }
            let attached = staged.authorization_id.as_deref().ok_or_else(|| {
                AutomationRunError::Processing(
                    "xai_image2_candidate_authorization_required: staged Job has no independent authorization"
                        .into(),
                )
            })?;
            let provider_authorization = provider
                .durable_authorization_id()
                .map_err(provider_error)?
                .ok_or_else(|| {
                    AutomationRunError::Processing(
                        "xai_image2_candidate_authorization_required: Provider has no durable authorization"
                            .into(),
                    )
                })?;
            if provider_authorization != attached {
                return Err(AutomationRunError::Processing(
                    "xai_image2_candidate_authorization_mismatch: Provider authorization does not match the staged Job"
                        .into(),
                ));
            }
            let attached_manifest_sha256 = staged
                .authorization_manifest_sha256
                .as_deref()
                .ok_or_else(|| {
                    AutomationRunError::Processing(
                        "xai_image2_candidate_authorization_manifest_missing: staged Job has no reviewed manifest digest"
                            .into(),
                    )
                })?;
            let provider_manifest_sha256 = provider
                .durable_authorization_manifest_sha256()
                .map_err(provider_error)?
                .ok_or_else(|| {
                    AutomationRunError::Processing(
                        "xai_image2_candidate_authorization_manifest_missing: Provider has no bound manifest digest"
                            .into(),
                    )
                })?;
            if provider_manifest_sha256 != attached_manifest_sha256 {
                return Err(AutomationRunError::Processing(
                    "xai_image2_candidate_authorization_manifest_mismatch: Provider manifest does not match the staged Job"
                        .into(),
                ));
            }
            provider
                .validate_durable_authorization_scope(
                    "xai",
                    "default",
                    super::XAI_IMAGE_2_CANDIDATE_MODEL,
                    "direction_grid",
                    1,
                    1,
                    super::XAI_IMAGE_2_CANDIDATE_MAX_COST_TICKS,
                    staged
                        .lineage_root_job_id
                        .as_deref()
                        .unwrap_or(&staged.job_id),
                    staged
                        .recipe_hash
                        .as_deref()
                        .expect("staged recipe hash was validated"),
                    staged
                        .input_hash
                        .as_deref()
                        .expect("staged input hash was validated"),
                )
                .map_err(provider_error)?;
            let source_dir = request.reuse_from_job_dir.as_deref().ok_or_else(|| {
                AutomationRunError::Processing(
                    "xai_image2_candidate_source_missing: approved V9 source is required".into(),
                )
            })?;
            super::plan::validate_topdown_cycle_direction_source(request, source_dir)
                .map_err(AutomationRunError::Plan)?;
            let source_job: JobRecord =
                serde_json::from_slice(&fs::read(source_dir.join("job.json"))?)?;
            let source_lineage = source_job
                .lineage_root_job_id
                .as_deref()
                .unwrap_or(&source_job.job_id);
            if staged.parent_job_id.as_deref() != Some(source_job.job_id.as_str())
                || staged.lineage_root_job_id.as_deref() != Some(source_lineage)
            {
                return Err(AutomationRunError::Processing(
                    "xai_image2_candidate_source_identity_changed: staged parent/lineage no longer matches the approved V9 source"
                        .into(),
                ));
            }
            if source_job.authorization_id.as_deref() == Some(attached) {
                return Err(AutomationRunError::Processing(
                    "xai_image2_candidate_authorization_not_independent: comparison cannot reuse the V9 source authorization"
                        .into(),
                ));
            }
        }
        if is_topdown_cycle_v101(request) {
            let source_dir = request.reuse_from_job_dir.as_deref().ok_or_else(|| {
                AutomationRunError::Processing(
                    "topdown_cycle_v101_source_missing: failed V10 source is required".into(),
                )
            })?;
            super::plan::validate_topdown_cycle_v101_source(request, source_dir)
                .map_err(AutomationRunError::Plan)?;
            let source_job: JobRecord =
                serde_json::from_slice(&fs::read(source_dir.join("job.json"))?)?;
            if staged.parent_job_id.as_deref() != Some(source_job.job_id.as_str())
                || staged.lineage_root_job_id.as_deref()
                    != Some(
                        source_job
                            .lineage_root_job_id
                            .as_deref()
                            .unwrap_or(&source_job.job_id),
                    )
                || staged.authorization_id.is_some()
            {
                return Err(AutomationRunError::Processing(
                    "topdown_cycle_v101_source_identity_changed: local replay parent, lineage, or zero-authorization boundary changed"
                        .into(),
                ));
            }
        }
        if is_topdown_cycle_v10(request)
            && !is_topdown_cycle_v101(request)
            && request.provider_id != "fixture"
        {
            let provider = provider.ok_or_else(|| {
                AutomationRunError::Processing(
                    "topdown_cycle_v10_authorization_required: real walk_down validation requires an independently authorized Provider"
                        .into(),
                )
            })?;
            if provider.id() != "xai"
                || request.profile_id != "default"
                || !request.validation_only
                || request.validation_animations != ["walk_down"]
                || request.metadata.default_animation != "walk_down"
                || request.generation.video_duration_seconds != 4
                || request.generation.video_model.as_deref() != Some("grok-imagine-video-1.5")
            {
                return Err(AutomationRunError::Processing(
                    "topdown_cycle_v10_real_scope_forbidden: staged recipe is not the exact xai/default Video 1.5 walk_down validation probe"
                        .into(),
                ));
            }
            let attached = staged.authorization_id.as_deref().ok_or_else(|| {
                AutomationRunError::Processing(
                    "topdown_cycle_v10_authorization_required: staged Job has no independent authorization"
                        .into(),
                )
            })?;
            let provider_authorization = provider
                .durable_authorization_id()
                .map_err(provider_error)?
                .ok_or_else(|| {
                    AutomationRunError::Processing(
                        "topdown_cycle_v10_authorization_required: Provider has no durable authorization"
                            .into(),
                    )
                })?;
            if provider_authorization != attached {
                return Err(AutomationRunError::Processing(
                    "topdown_cycle_v10_authorization_mismatch: Provider authorization does not match the staged Job"
                        .into(),
                ));
            }
            let attached_manifest_sha256 = staged
                .authorization_manifest_sha256
                .as_deref()
                .ok_or_else(|| {
                    AutomationRunError::Processing(
                        "topdown_cycle_v10_authorization_manifest_missing: staged Job has no reviewed manifest digest"
                            .into(),
                    )
                })?;
            let provider_manifest_sha256 = provider
                .durable_authorization_manifest_sha256()
                .map_err(provider_error)?
                .ok_or_else(|| {
                    AutomationRunError::Processing(
                        "topdown_cycle_v10_authorization_manifest_missing: Provider has no bound manifest digest"
                            .into(),
                    )
                })?;
            if provider_manifest_sha256 != attached_manifest_sha256 {
                return Err(AutomationRunError::Processing(
                    "topdown_cycle_v10_authorization_manifest_mismatch: Provider manifest does not match the staged Job"
                        .into(),
                ));
            }
            provider
                .validate_durable_authorization_scope(
                    "xai",
                    "default",
                    "grok-imagine-video-1.5",
                    "walk_down:video",
                    1,
                    1,
                    3_300_000_000,
                    staged
                        .lineage_root_job_id
                        .as_deref()
                        .unwrap_or(&staged.job_id),
                    staged
                        .recipe_hash
                        .as_deref()
                        .expect("staged recipe hash was validated"),
                    staged
                        .input_hash
                        .as_deref()
                        .expect("staged input hash was validated"),
                )
                .map_err(provider_error)?;
            let source_dir = request.reuse_from_job_dir.as_deref().ok_or_else(|| {
                AutomationRunError::Processing(
                    "topdown_cycle_v10_source_missing: approved V9 source is required".into(),
                )
            })?;
            let source_job: JobRecord =
                serde_json::from_slice(&fs::read(source_dir.join("job.json"))?)?;
            if staged.parent_job_id.as_deref() != Some(source_job.job_id.as_str())
                || staged.lineage_root_job_id.as_deref()
                    != Some(
                        source_job
                            .lineage_root_job_id
                            .as_deref()
                            .unwrap_or(&source_job.job_id),
                    )
            {
                return Err(AutomationRunError::Processing(
                    "topdown_cycle_v10_source_identity_changed: staged parent/lineage no longer matches the approved V9 source"
                        .into(),
                ));
            }
            if source_job.authorization_id.as_deref() == Some(attached) {
                return Err(AutomationRunError::Processing(
                    "topdown_cycle_v10_authorization_not_independent: V10 cannot reuse the V9 source authorization"
                        .into(),
                ));
            }
        }
    }
    let mut claimed = false;
    let running = store.update_record(job_id, |record| {
        if record.lifecycle_state == JobLifecycleState::Queued
            && !record.cancellation_requested
            && record.recipe.as_ref() == Some(&canonical_operation)
            && record.recipe_hash.as_deref() == Some(canonical_recipe_hash.as_str())
            && record.input_hash.as_deref() == Some(current_input_fingerprint.as_str())
        {
            claimed = true;
            record.lifecycle_state = JobLifecycleState::Running;
            record.progress = 0.02;
            record.worker_pid = Some(std::process::id());
            record.next_actions = vec!["poll_job".to_string(), "cancel_job".to_string()];
        }
    })?;
    if !claimed {
        return Err(AutomationRunError::Processing(format!(
            "job_execution_not_queued: job {job_id} is {:?}; a staged Job may execute exactly once",
            running.lifecycle_state
        )));
    }
    // BuildProject is an orchestrator: only its child jobs call the Provider.
    // Tracking the shared provider again at the parent would duplicate every
    // child request in provider-usage.json.
    let usage_provider = if matches!(operation, AutomationOperation::BuildProject(_)) {
        None
    } else {
        provider
    };
    let provider_usage_baseline = usage_provider.map(MediaGenerationProvider::usage);
    check_cancelled(store, job_id)?;
    let result = match operation {
        AutomationOperation::PrepareAsset(request) => run_prepare_asset(store, job_id, request),
        AutomationOperation::PrepareCharacterPack(request) => {
            run_prepare_character_pack(store, job_id, request)
        }
        AutomationOperation::GenerateCharacterPack(request) => {
            let provider = provider.ok_or_else(|| {
                AutomationRunError::Processing(format!(
                    "provider {} must be resolved before running this plan",
                    request.provider_id
                ))
            })?;
            run_generate_character_pack(store, job_id, request, provider)
        }
        AutomationOperation::ImportDirectionGrid(request) => {
            run_import_direction_grid(store, job_id, request)
        }
        AutomationOperation::CreateStyleLock(request) => {
            let provider = provider.ok_or_else(|| {
                AutomationRunError::Processing(format!(
                    "provider {} must be resolved before running this plan",
                    request.provider_id
                ))
            })?;
            run_create_style_lock(store, job_id, request, provider)
        }
        AutomationOperation::CreateSubjectLock(request) => {
            run_create_subject_lock(store, job_id, request, provider)
        }
        AutomationOperation::CreateCollectionLock(request) => {
            if collection_requires_provider(&request.spec_path)
                .map_err(|error| AutomationRunError::Processing(error.to_string()))?
            {
                let provider = provider.ok_or_else(|| {
                    AutomationRunError::Processing(format!(
                        "provider {} must be resolved before creating this Collection Lock",
                        request.provider_id
                    ))
                })?;
                run_create_collection_lock(store, job_id, request, Some(provider))
            } else {
                run_create_collection_lock(store, job_id, request, None)
            }
        }
        AutomationOperation::GenerateStaticAssetSet(request) => {
            run_generate_static_asset_set(store, job_id, request, provider)
        }
        AutomationOperation::CreateEnvironmentLock(request) => {
            let provider = provider.ok_or_else(|| {
                AutomationRunError::Processing(format!(
                    "provider {} must be resolved before running this plan",
                    request.provider_id
                ))
            })?;
            run_create_environment_lock(store, job_id, request, provider)
        }
        AutomationOperation::GenerateTerrainSet(request) => {
            let provider = provider.ok_or_else(|| {
                AutomationRunError::Processing(format!(
                    "provider {} must be resolved before running this plan",
                    request.provider_id
                ))
            })?;
            run_generate_terrain_set(store, job_id, request, provider)
        }
        AutomationOperation::GenerateBuildingKit(request) => {
            let provider = provider.ok_or_else(|| {
                AutomationRunError::Processing(format!(
                    "provider {} must be resolved before running this plan",
                    request.provider_id
                ))
            })?;
            run_generate_building_kit(store, job_id, request, provider)
        }
        AutomationOperation::CompileMap(request) => run_compile_map(store, job_id, request),
        AutomationOperation::InstallGodot(request) => run_install_godot(store, job_id, request),
        AutomationOperation::BuildProject(request) => {
            // Children are planned through the same PlanStore the CLI uses:
            // FORGE_PLAN_STORE when set, otherwise the default app store.
            // The parent build job itself makes no provider calls; every
            // child goes back through run_operation_with_provider so the
            // real-provider cost guard stays in force.
            let plans = match std::env::var_os("FORGE_PLAN_STORE") {
                Some(root) => PlanStore::new(root),
                None => PlanStore::default_app_store(),
            }
            .map_err(AutomationRunError::Plan)?;
            crate::game_art::run_build_project(store, &plans, job_id, request, provider)
                .and_then(|_report| store.read_record(job_id).map_err(AutomationRunError::Job))
        }
    };
    if result.is_err() && operation_is_video_character(operation) {
        if let (
            AutomationOperation::GenerateCharacterPack(request),
            Some(provider),
            Some(provider_usage_baseline),
        ) = (operation, provider, provider_usage_baseline.as_ref())
        {
            let _ = persist_failed_character_provider_manifest(
                store,
                job_id,
                request,
                provider,
                provider_usage_baseline,
            );
        }
    }
    let usage_result = usage_provider.map(|provider| {
        persist_provider_usage(
            store,
            job_id,
            provider,
            provider_usage_baseline
                .as_ref()
                .expect("Provider baseline exists"),
        )
    });
    let local_usage_result = if usage_provider.is_none()
        && matches!(
            operation,
            AutomationOperation::GenerateStaticAssetSet(request)
                if request.consistency_recheck_only
        )
        || matches!(operation, AutomationOperation::ImportDirectionGrid(_))
    {
        let provider_id = match operation {
            AutomationOperation::GenerateStaticAssetSet(request) => &request.provider_id,
            AutomationOperation::ImportDirectionGrid(_) => "external_import",
            _ => unreachable!(),
        };
        Some(persist_zero_provider_usage(store, job_id, provider_id))
    } else {
        None
    };

    match result {
        Ok(record) => {
            if let Some(usage_result) = usage_result {
                usage_result?;
                return store.read_record(&record.job_id).map_err(Into::into);
            }
            if let Some(usage_result) = local_usage_result {
                usage_result?;
                return store.read_record(&record.job_id).map_err(Into::into);
            }
            Ok(record)
        }
        Err(AutomationRunError::Cancelled)
        | Err(AutomationRunError::Provider(ProviderError::Cancelled)) => {
            if let Some(usage_result) = usage_result {
                usage_result?;
            }
            let record = store.update_record(job_id, |record| {
                record.lifecycle_state = JobLifecycleState::Cancelled;
                record.progress = 1.0;
                record.worker_pid = None;
                record.error_code = Some("cancelled".into());
                record.next_actions = vec!["job_report".into()];
            })?;
            Ok(record)
        }
        Err(error) => {
            let _ = usage_result.transpose();
            let message = error.to_string();
            let error_code = error.code();
            let resumable_static =
                matches!(operation, AutomationOperation::GenerateStaticAssetSet(_))
                    && matches!(
                        error_code,
                        "provider_request_failed"
                            | "provider_unavailable"
                            | "provider_rate_limited"
                            | "provider_io_error"
                    );
            let _ = store.update_record(job_id, |record| {
                record.lifecycle_state = JobLifecycleState::Failed;
                record.state = JobState::Failed;
                record.worker_pid = None;
                record.error_summary = Some(message.clone());
                record.error_code = Some(error_code.into());
                record.recoverable = true;
                record.next_actions = if resumable_static {
                    vec!["job_report".into(), "retry_job".into()]
                } else {
                    vec!["job_report".into(), "prepare_new_plan".into()]
                };
            });
            Err(error)
        }
    }
}

fn operation_is_video_character(operation: &AutomationOperation) -> bool {
    matches!(
        operation,
        AutomationOperation::GenerateCharacterPack(request)
            if request.workflow.id == "topdown" && request.workflow.version == "1.0.0"
    )
}

fn persist_provider_usage(
    store: &JobStore,
    job_id: &str,
    provider: &dyn MediaGenerationProvider,
    baseline: &ProviderUsage,
) -> Result<(), AutomationRunError> {
    let record = store.read_record(job_id)?;
    let path = record.job_dir.join("provider-usage.json");
    let value = serde_json::json!({
        "schemaVersion": "1",
        "providerId": provider.id(),
        "usage": provider_usage_delta(&provider.usage(), baseline),
    });
    write_json_atomic(&path, &value)?;
    let sha256 = hash_file(&path)?;
    store.update_record(job_id, |record| {
        record
            .artifacts
            .retain(|artifact| artifact.kind != "provider_usage");
        record.artifacts.push(JobArtifactRecord {
            kind: "provider_usage".into(),
            path: path.clone(),
            sha256: Some(sha256.clone()),
        });
    })?;
    Ok(())
}

fn persist_zero_provider_usage(
    store: &JobStore,
    job_id: &str,
    provider_id: &str,
) -> Result<(), AutomationRunError> {
    let record = store.read_record(job_id)?;
    let path = record.job_dir.join("provider-usage.json");
    let value = serde_json::json!({
        "schemaVersion": "1",
        "providerId": provider_id,
        "usage": ProviderUsage::default(),
    });
    write_json_atomic(&path, &value)?;
    let sha256 = hash_file(&path)?;
    store.update_record(job_id, |record| {
        record
            .artifacts
            .retain(|artifact| artifact.kind != "provider_usage");
        record.artifacts.push(JobArtifactRecord {
            kind: "provider_usage".into(),
            path: path.clone(),
            sha256: Some(sha256.clone()),
        });
    })?;
    Ok(())
}

fn provider_usage_delta(current: &ProviderUsage, baseline: &ProviderUsage) -> ProviderUsage {
    ProviderUsage {
        requests: current.requests.saturating_sub(baseline.requests),
        generated_images: current
            .generated_images
            .saturating_sub(baseline.generated_images),
        generated_videos: current
            .generated_videos
            .saturating_sub(baseline.generated_videos),
        edited_videos: current.edited_videos.saturating_sub(baseline.edited_videos),
        private_file_uploads: current
            .private_file_uploads
            .saturating_sub(baseline.private_file_uploads),
        cost_in_usd_ticks: current
            .cost_in_usd_ticks
            .map(|current| current.saturating_sub(baseline.cost_in_usd_ticks.unwrap_or_default())),
    }
}

