    fn direction_motion_test_subject(stepping: bool) -> RgbaImage {
        let mut image = RgbaImage::from_pixel(128, 128, Rgba([0, 0, 0, 0]));
        for y in 30..92 {
            for x in 45..83 {
                image.put_pixel(x, y, Rgba([80, 110, 70, 255]));
            }
        }
        if stepping {
            for y in 92..120 {
                for x in 35..50 {
                    image.put_pixel(x, y, Rgba([80, 110, 70, 255]));
                }
                for x in 78..94 {
                    image.put_pixel(x, y, Rgba([80, 110, 70, 255]));
                }
            }
        } else {
            for y in 92..120 {
                for x in 50..64 {
                    image.put_pixel(x, y, Rgba([80, 110, 70, 255]));
                }
                for x in 66..80 {
                    image.put_pixel(x, y, Rgba([80, 110, 70, 255]));
                }
            }
        }
        image
    }

    #[test]
    fn canonical_front_idle_rejects_a_biped_step_as_the_stable_reference() {
        let stable = direction_motion_test_subject(false);
        let stepping = direction_motion_test_subject(true);
        let stable_feedback = direction_motion_feedback_with_role(
            None,
            &stable,
            false,
            Some(DirectionMotionNodeRoleV1::FrontIdle),
            CharacterMotionProfileV1::BipedWalk,
        );
        assert_eq!(stable_feedback.verdict, ConsistencyVerdict::GameReady);
        assert!(!stable_feedback
            .reasons
            .contains(&"canonical_idle_not_stable_stance".into()));

        let stepping_feedback = direction_motion_feedback_with_role(
            None,
            &stepping,
            false,
            Some(DirectionMotionNodeRoleV1::FrontIdle),
            CharacterMotionProfileV1::BipedWalk,
        );
        assert_eq!(stepping_feedback.verdict, ConsistencyVerdict::Regenerate);
        assert!(stepping_feedback
            .reasons
            .contains(&"canonical_idle_not_stable_stance".into()));
    }

