    #[test]
    fn temporal_alpha_cleanup_removes_specks_and_fills_single_frame_holes() {
        let mut frames = vec![RgbaImage::from_pixel(16, 16, Rgba([0, 0, 0, 0])); 3];
        for frame in &mut frames {
            for y in 4..12 {
                for x in 4..12 {
                    frame.put_pixel(x, y, Rgba([80, 100, 60, 255]));
                }
            }
        }
        frames[1].put_pixel(7, 7, Rgba([0, 0, 0, 0]));
        frames[1].put_pixel(14, 2, Rgba([255, 255, 255, 255]));

        let counts = stabilize_character_alpha_temporally(&mut frames, 48);

        assert_eq!(frames[1].get_pixel(14, 2)[3], 0);
        assert!(frames[1].get_pixel(7, 7)[3] > 48);
        assert!(counts[1].removed_pixels >= 1);
        assert!(counts[1].filled_pixels >= 1);
        assert!(counts[1].max_boundary_distance_px <= 1);
    }

