    #[test]
    fn action_consistency_uses_direction_palette_and_changes_with_selected_frames() {
        let temp = tempfile::tempdir().unwrap();
        let anchor_path = temp.path().join("anchor.png");
        let mut anchor = RgbaImage::from_pixel(96, 96, Rgba([0, 0, 0, 0]));
        for y in 16..86 {
            for x in 30..66 {
                anchor.put_pixel(x, y, Rgba([130, 60, 210, 255]));
            }
        }
        anchor.save(&anchor_path).unwrap();
        let normalized =
            normalize_static_image(&anchor_path, &temp.path().join("normalized.png"), 128, true)
                .unwrap();
        let style = StyleLockV1 {
            schema_version: "1".into(),
            revision: "style-action-test".into(),
            provider_id: "fixture".into(),
            profile_id: "default".into(),
            image_model: Some("fixture-image".into()),
            prompt: "red environment board".into(),
            perspective: "topdown".into(),
            lighting: "flat".into(),
            outline: "dark".into(),
            background: "transparent".into(),
            sampling: SamplingMode::Nearest,
            character_canvas_size: 128,
            icon_canvas_size: 128,
            prop_canvas_size: 128,
            board_path: anchor_path.clone(),
            board_sha256: "board".into(),
            reference_sha256: Vec::new(),
            baseline_profile: crate::asset_project::STYLE_BASELINE_PROFILE.into(),
            migrated_from_revision: None,
            baseline: StyleBaseline {
                palette: vec![PaletteColor {
                    color: "#dc3c28".into(),
                    weight: 1.0,
                }],
                edge_density: 0.1,
                foreground_scale: 0.5,
                perceptual_hash: "0".into(),
            },
        };
        let direction_lock = DirectionLockV1 {
            schema_version: "1".into(),
            profile: DIRECTION_LOCK_PROFILE.into(),
            workflow: "topdown-video-locked@5.0.0".into(),
            provider_id: "fixture".into(),
            profile_id: "default".into(),
            model: "fixture-image".into(),
            style_revision: style.revision.clone(),
            subject_id: "subject".into(),
            subject_revision: "revision".into(),
            subject_sha256: "subject-sha".into(),
            equipment_kind: CharacterEquipmentKindV1::None,
            equipment_reference_sha256: None,
            entries: vec![DirectionLockEntryV1 {
                direction: DirectionViewV1::Front,
                animation: "direction_front".into(),
                frame: 0,
                attempt: 1,
                generation_master_path: None,
                generation_master_sha256: None,
                path: anchor_path,
                sha256: "anchor-sha".into(),
                assessment: assess_direction_anchor(
                    &anchor,
                    "faceless abstract test character",
                    DirectionViewV1::Front,
                ),
            }],
        };
        let attempts = BTreeMap::from([("idle".into(), 2)]);
        let baseline_frames = BTreeMap::from([("idle".into(), vec![normalized.clone(); 8])]);
        let baseline = evaluate_character_action_consistency(
            temp.path(),
            &style,
            &direction_lock,
            &baseline_frames,
            &attempts,
        )
        .unwrap();
        assert_eq!(baseline.profile, CHARACTER_ACTION_CONSISTENCY_PROFILE);
        assert!(baseline.items[0].metrics.palette_overlap >= 0.99);
        assert_eq!(baseline.items[0].attempt, 2);

        let mut changed = normalized;
        for y in 48..96 {
            for x in 24..104 {
                changed.put_pixel(x, y, Rgba([220, 40, 30, 255]));
            }
        }
        let changed_frames = BTreeMap::from([("idle".into(), vec![changed; 8])]);
        let changed_report = evaluate_character_action_consistency(
            temp.path(),
            &style,
            &direction_lock,
            &changed_frames,
            &attempts,
        )
        .unwrap();
        let baseline_bytes = serde_json::to_vec(&baseline).unwrap();
        let changed_bytes = serde_json::to_vec(&changed_report).unwrap();
        assert_ne!(
            Sha256::digest(&baseline_bytes),
            Sha256::digest(&changed_bytes)
        );
        assert!(changed_report.items[0].metrics.palette_overlap < 0.70);
    }

